import React, { useState } from 'react'
import Typography from '../Typography/Typography'
import type { TimeInputProps } from './TimeInput'
import TimeInput from './TimeInput'

export default {
  title: 'Components/TimeInput',
  component: TimeInput,
  argTypes: {
    defaultValue: {
      control: { type: 'none' },
      table: {
        category: 'Content',
      },
    },
    disabled: {
      table: {
        category: 'State',
      },
    },
    error: {
      table: {
        category: 'State',
      },
    },
    errorMessage: {
      table: {
        category: 'Content',
      },
    },
    helperText: {
      table: {
        category: 'Content',
      },
    },
    hourCycle: {
      control: { type: 'select' },
      options: [undefined, 12, 24],
      table: {
        category: 'Appearance',
      },
    },
    label: {
      table: {
        category: 'Content',
      },
    },
    name: {
      table: {
        category: 'Content',
      },
    },
    required: {
      table: {
        category: 'State',
      },
    },
    size: {
      control: { type: 'select' },
      options: ['medium', 'small'],
      table: {
        category: 'Appearance',
      },
    },
    validationBehavior: {
      control: { type: 'select' },
      options: ['aria', 'native'],
      table: {
        category: 'State',
      },
    },
    value: {
      control: { type: 'none' },
      table: {
        category: 'Content',
      },
    },
    variant: {
      control: { type: 'select' },
      options: ['outlined', 'filled'],
      table: {
        category: 'Appearance',
      },
    },
  },
  args: {
    label: 'Start time',
    size: 'medium',
    variant: 'outlined',
  },
}

function Template(args: TimeInputProps): JSX.Element {
  const [value, setValue] = useState<string | null>('09:00')

  return (
    <div className="w-64 space-y-4">
      <TimeInput {...args} onChange={setValue} value={value} />
      <div className="mt-2 ml-2">
        <Typography variant="body2">Value: {value ?? '—'}</Typography>
      </div>
    </div>
  )
}

export const Default = {
  render: Template,
}

export function HourCycle(): JSX.Element {
  return (
    <div className="flex flex-row p-8 space-x-6">
      <div className="w-64 space-y-2">
        <Typography variant="body2">Locale default</Typography>
        <TimeInput defaultValue="17:05" label="Start time" />
      </div>
      <div className="w-64 space-y-2">
        <Typography variant="body2">12 hour</Typography>
        <TimeInput defaultValue="17:05" hourCycle={12} label="Start time" />
      </div>
      <div className="w-64 space-y-2">
        <Typography variant="body2">24 hour</Typography>
        <TimeInput defaultValue="17:05" hourCycle={24} label="Start time" />
      </div>
    </div>
  )
}

export function Steps(): JSX.Element {
  return (
    <div className="flex flex-row p-8 space-x-6">
      <div className="w-64 space-y-2">
        <Typography variant="body2">Default 5 minute steps</Typography>
        <TimeInput
          defaultValue="09:00"
          helperText="Focus the minutes and press up or down"
          label="Start time"
        />
      </div>
      <div className="w-64 space-y-2">
        <Typography variant="body2">Off the step, snaps on</Typography>
        <TimeInput
          defaultValue="09:07"
          helperText="Up goes to 10, down goes to 05"
          label="Start time"
        />
      </div>
      <div className="w-64 space-y-2">
        <Typography variant="body2">Empty</Typography>
        <TimeInput
          helperText="The first press fills in 00"
          label="Start time"
        />
      </div>
    </div>
  )
}

function renderStates(
  size: 'medium' | 'small',
  variant: 'filled' | 'outlined',
): JSX.Element {
  return (
    <div className="flex flex-col p-6 space-y-6 w-72" key={size}>
      <TimeInput label="Empty" size={size} variant={variant} />
      <TimeInput
        defaultValue="09:05"
        label="With a value"
        size={size}
        variant={variant}
      />
      <TimeInput
        defaultValue="09:05"
        helperText="Shifts start on the hour or half hour"
        label="With helper text"
        size={size}
        variant={variant}
      />
      <TimeInput
        error
        errorMessage="Choose a start time"
        label="In an error state"
        size={size}
        variant={variant}
      />
      <TimeInput
        defaultValue="09:05"
        disabled
        label="Disabled"
        size={size}
        variant={variant}
      />
      <TimeInput label="Required" required size={size} variant={variant} />
    </div>
  )
}

export function Outlined(): JSX.Element {
  return (
    <div className="flex flex-row p-8">
      {renderStates('medium', 'outlined')}
      {renderStates('small', 'outlined')}
    </div>
  )
}

export function Filled(): JSX.Element {
  return (
    <div className="flex flex-row p-8">
      {renderStates('medium', 'filled')}
      {renderStates('small', 'filled')}
    </div>
  )
}
