/* eslint-disable react/forbid-component-props */
import { Time } from '@internationalized/date'
import React, { useContext, useRef } from 'react'
import type { ReactNode } from 'react'
import {
  DateInput,
  DateSegment,
  FieldError,
  I18nProvider,
  Label,
  Text,
  TimeField as AriaTimeField,
  TimeFieldStateContext,
} from 'react-aria-components'
import { useIntl } from 'react-intl'
import Schedule from '../icons/Schedule'
import type {
  TextInputSize,
  TextInputStatus,
  TextInputVariant,
} from '../TextInput/styles'
import { baseClasses } from '../TextInput/styles'
import type { FieldStyles } from '../TextInput/useFieldStyles'
import { useFieldStyles } from '../TextInput/useFieldStyles'
import { toTime, toTimeString } from './time'

export interface TimeInputProps {
  /**
   * The initially selected time as a 24-hour "HH:mm" string, ex "09:05" (uncontrolled)
   */
  defaultValue?: string | null
  /**
   * Whether the input is disabled or not
   * @default false
   */
  disabled?: boolean
  /**
   * Whether the input is in an error state
   * @default false
   */
  error?: boolean
  /**
   * The error message to display below the input while `error` is true
   */
  errorMessage?: ReactNode
  /**
   * The descriptive text that sits below the input field. For errors, use
   * `errorMessage` combined with `error`
   */
  helperText?: ReactNode
  /**
   * Display format of the input, 1:13pm or 13:13. The value of the input is always 24hr under the hood.
   * If this prop is not specified then it will default to the system's locale
   */
  hourCycle?: 12 | 24
  /**
   * The label that sits at the top left of the input
   */
  label: ReactNode
  /**
   * The name used when including this input in an HTML form.
   * Note that the submitted value is an ISO time with seconds, e.g. "09:05:00"
   */
  name?: string
  /**
   * Callback invoked with the selected time as a 24-hour "HH:mm" string, or
   * null when the value is cleared. Only fires once every segment is filled in
   */
  onChange?: (value: string | null) => void
  /**
   * Whether user input is required before form submission
   * @default false
   */
  required?: boolean
  /**
   * The size of the input
   * @default 'medium'
   */
  size?: TextInputSize
  /**
   * How validation is surfaced. 'aria' (the default) exposes validity to
   * assistive technology without blocking native form submission; 'native'
   * uses the browser's built-in form validation
   * @default 'aria'
   */
  validationBehavior?: 'aria' | 'native'
  /**
   * The selected time as a 24 hour format string, ex 19:05 (controlled)
   */
  value?: string | null
  /**
   * The visual style variant of the input field
   * @default 'outlined'
   */
  variant?: TextInputVariant
}

const STEP_MINUTES = 5

interface SteppedDateInputProps {
  className: FieldStyles['segment']
}

function SteppedDateInput({ className }: SteppedDateInputProps): JSX.Element {
  const state = useContext(TimeFieldStateContext)

  if (state) {
    const { decrement, increment, incrementToMax } = state

    const cycleMinute = (amount: number) => {
      const minute = state.segments.find((segment) => segment.type === 'minute')

      if (!minute) {
        return
      }

      if (minute.isPlaceholder) {
        state.setSegment('minute', minute.value ?? 0)

        return
      }

      state.setSegment(
        'minute',
        new Time(0, minute.value ?? 0).cycle('minute', amount, { round: true })
          .minute,
      )
    }

    state.decrement = (type) =>
      type === 'minute' ? cycleMinute(-STEP_MINUTES) : decrement(type)

    state.increment = (type) =>
      type === 'minute' ? cycleMinute(STEP_MINUTES) : increment(type)

    state.incrementToMax = (type) =>
      type === 'minute'
        ? state.setSegment('minute', 60 - STEP_MINUTES)
        : incrementToMax(type)
  }

  return (
    <DateInput className="flex items-center flex-1 min-w-0 px-1">
      {(segment) => <DateSegment className={className} segment={segment} />}
    </DateInput>
  )
}

function TimeInput({
  defaultValue,
  disabled = false,
  error = false,
  errorMessage,
  helperText,
  hourCycle,
  label,
  name,
  onChange,
  required = false,
  size = 'medium',
  validationBehavior = 'aria',
  value,
  variant = 'outlined',
}: TimeInputProps): JSX.Element {
  const intl = useIntl()
  const status: TextInputStatus = disabled
    ? 'disabled'
    : error
    ? 'error'
    : 'default'
  const styles = useFieldStyles(size, status, variant)
  const fieldRef = useRef<HTMLDivElement>(null)

  // A press that lands on a segment selects that segment, so leave it be
  const focusHour = (event: React.PointerEvent) => {
    if ((event.target as HTMLElement).closest('[role="spinbutton"]')) {
      return
    }

    event.preventDefault()
    event.stopPropagation()

    // If the user already has the input focused and say, misses a segment, we do not want to shift their focus
    if (fieldRef.current?.contains(document.activeElement)) {
      return
    }

    fieldRef.current?.querySelector<HTMLElement>('[data-type="hour"]')?.focus()
  }

  return (
    <I18nProvider locale={intl.locale}>
      <AriaTimeField
        className={baseClasses.container}
        granularity="minute"
        isDisabled={disabled}
        isInvalid={error || undefined}
        isRequired={required}
        onChange={(time) => onChange?.(toTimeString(time))}
        validationBehavior={validationBehavior}
        {...(hourCycle && { hourCycle })}
        {...(name && { name })}
        {...(defaultValue !== undefined && {
          defaultValue: toTime(defaultValue),
        })}
        {...(value !== undefined && { value: toTime(value) })}
      >
        <div
          className={styles.group}
          onPointerDownCapture={focusHour}
          ref={fieldRef}
        >
          <Label className={styles.label}>{label}</Label>
          <span className={styles.icon}>
            <Schedule />
          </span>
          <SteppedDateInput className={styles.segment} />
        </div>
        {helperText ? (
          <Text className={styles.help} slot="description">
            {helperText}
          </Text>
        ) : null}
        {errorMessage ? (
          <FieldError className={styles.error}>{errorMessage}</FieldError>
        ) : null}
      </AriaTimeField>
    </I18nProvider>
  )
}

export default TimeInput
