import type { Time } from '@internationalized/date'
import { parseTime } from '@internationalized/date'

/**
 * "HH:mm" or "HH:mm:ss"
 */
const TIME_PATTERN = /^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$/

/**
 * Converts a HH:mm string into the time value used by React Aria
 *
 * @param value
 */
export function toTime(value: string | null | undefined): Time | null {
  return value && TIME_PATTERN.test(value) ? parseTime(value) : null
}

/**
 * Converts an hour and minute back to a HH:mm string
 *
 * @param value
 */
export function toTimeString(
  value: { hour: number; minute: number } | null,
): string | null {
  return value
    ? `${String(value.hour).padStart(2, '0')}:${String(value.minute).padStart(
        2,
        '0',
      )}`
    : null
}
